head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > arrowMove]<br/>Cell 의 Caret 이 첫번째 또는 마지막 문자에 있을때 좌/우 방향키로 Cell 이동을 허용할지 설정합니다.",
    "validation" : [
        "moveKeyEditMode=true 인 경우에 동작하며 moveKeyEditModeAll=true 이면 항상 true 로 동작합니다.",
        "true 설정 시 Cell 이 빈값이거나 Caret 이 첫번째 또는 마지막 문자에 있을때 좌/우 방향키 입력 시 인접 Cell 로 이동합니다.",
        "false(기본값) 설정 시 Cell 이 빈값인 경우 좌/우 방향키 입력 시 인접 Cell 로 이동합니다.",
        "false(기본값) 설정 시 Cell 에 값이 입력된 경우 Caret 의 위치만 이동합니다.",
        "Column 의 inputType 속성값이 'text','secret','textImage','drilldown' 인 경우에 동작합니다.",
        "focusmove 속성값이 'true','horizontal' 인 경우에 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // arrowMove 동작 전제 충족: arrowMove=true(기본), moveKeyEditMode=true, focusMove=true
    con_arrowMove.setValue("true");
    con_moveKeyEditMode.setValue("true");
    con_focusMove.setValue("true");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기
    let arrowMoveVal = con_arrowMove.getValue();
    let moveKeyEditModeVal = con_moveKeyEditMode.getValue();
    let moveKeyEditModeAllVal = con_moveKeyEditModeAll.getValue();
    let focusMoveVal = con_focusMove.getValue();

    // 동작 조건/현재 설정 라벨 생성
    $c.gcm.createLabel('label="전제조건: Column inputType = text / secret / textImage / drilldown + focusMove 속성값이 true 또는 horizontal + moveKeyEditMode=true (arrowMove 동작 조건 충족)"', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: arrowMove=' + (arrowMoveVal === '' ? '미설정(기본 false)' : arrowMoveVal) + ' / moveKeyEditMode=' + (moveKeyEditModeVal === '' ? '미설정(기본 false)' : moveKeyEditModeVal) + ' / moveKeyEditModeAll=' + (moveKeyEditModeAllVal === '' ? '미설정(기본 false)' : moveKeyEditModeAllVal) + ' / focusMove=' + (focusMoveVal === '' ? '미설정(기본 true)' : focusMoveVal) + '"', '', 'label2');
    $c.gcm.createLabel('label="사용법: 셀을 더블클릭하여 편집모드로 진입한 뒤 좌/우 방향키를 누르세요(선택만 한 상태에서는 동작하지 않음). 편집모드에서 Caret 이 첫/마지막 문자이거나 빈값 셀일 때 좌/우 방향키를 누르면 인접 Cell 로 이동하며 편집모드가 유지됩니다(arrowMove=true)."', '', 'label3');
    $c.gcm.createLabel('label="데이터: 빈값 셀(col1 row1/row3, col2 row2/row4)은 바로 이동하고, 값 있는 셀(2자 이상)은 Caret 이 첫/마지막 문자일 때만(arrowMove=true) 또는 빈값일 때만(false) 이동함을 확인하세요."', '', 'label4');

    // dataList 직접 생성 (4행)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    // drilldown 컬럼(col4) 계층: 행마다 depth(레벨)를 다르게 부여하여 실제 트리 구조(들여쓰기)가 렌더되도록 구성
    //  row1=depth1(루트) / row2=depth2(row1의 자식) / row3=depth3(row2의 자식) / row4=depth2(row1의 자식)
    let depthArr = [1, 2, 3, 2];
    // 빈값/값 혼합 구성: 빈값 Cell 에서 좌/우 방향키 인접 Cell 이동(validation #2/#3) 검증 가능하도록 구성
    //  col1(text)  : row1 빈값 / row2 값(abc2) / row3 빈값 / row4 값(abc4)
    //  col2(secret): row1 값(sec1) / row2 빈값 / row3 값(sec3) / row4 빈값
    //  값 있는 셀은 Caret 첫/마지막 vs 중간 구분이 가능하도록 2자 이상 문자열 사용
    let col1Arr = ['', 'abc2', '', 'abc4'];
    let col2Arr = ['sec1', '', 'sec3', ''];
    for (let r = 1; r <= 4; r++) {
        strDl += '<w2:row>';
        strDl += '<col1><![CDATA[' + col1Arr[r - 1] + ']]></col1>';
        strDl += '<col2><![CDATA[' + col2Arr[r - 1] + ']]></col2>';
        strDl += '<col3><![CDATA[img' + r + ']]></col3>';
        strDl += '<col4><![CDATA[D' + r + ']]></col4>';
        strDl += '<depth><![CDATA[' + depthArr[r - 1] + ']]></depth>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // arrowMove / moveKeyEditMode / moveKeyEditModeAll / focusMove 속성 (미설정 시 속성 미부여 = 기본값)
    let arrowMoveAttr = arrowMoveVal === '' ? '' : 'arrowMove="' + arrowMoveVal + '" ';
    let mkemAttr = moveKeyEditModeVal === '' ? '' : 'moveKeyEditMode="' + moveKeyEditModeVal + '" ';
    let mkemAllAttr = moveKeyEditModeAllVal === '' ? '' : 'moveKeyEditModeAll="' + moveKeyEditModeAllVal + '" ';
    let focusMoveAttr = focusMoveVal === '' ? '' : 'focusMove="' + focusMoveVal + '" ';

    // target 생성 (전제조건: inputType = text/secret/textImage/drilldown + focusMove = con_focusMove 값)
    //  col1=text, col2=secret, col3=textImage(imageSrc+viewType=icon), col4=drilldown(depthColumn=depth)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + arrowMoveAttr + mkemAttr + mkemAllAttr + focusMoveAttr + 'editModeEvent="ondblclick" dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="column1" value="text"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column2" value="secret"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column3" value="textImage"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column4" value="drilldown"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" dataType="text" id="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="secret" dataType="text" id="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_filter.svg" dataType="text" id="col3"></w2:column>';
    strTarget += '<w2:column width="140" inputType="drilldown" depthColumn="depth" depthStartIndex="1" dataType="text" id="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 좌/우 방향키 입력 후, 이동된 Cell 위치 + 편집 모드 여부 자동 출력
    // (편집 모드에서는 키 이벤트가 셀 내부 편집 input 으로 가서 gridView onkeyup 프로퍼티 핸들러가 fire 되지 않으므로
    //  document 에 capture-phase keyup 리스너를 1회 등록하여 편집 input 의 방향키 keyup 도 포착)
    if (typeof scwin.moveKeyHandler === 'function') {
        document.removeEventListener('keyup', scwin.moveKeyHandler, true);
    }
    scwin.moveKeyHandler = function (ev) {
        let key = ev && (ev.keyCode || ev.which);
        // 좌(37)/우(39) 방향키일 때만 이동 결과 출력
        if (key !== 37 && key !== 39) {
            return;
        }
        // 현재 target1 그리드의 셀(또는 셀 내부 편집 input)에서 발생한 이벤트인지 확인
        let gridEl = document.getElementById(scwin.target1.id);
        if (!gridEl || !ev.target || !gridEl.contains(ev.target)) {
            return;
        }
        let dir = key === 37 ? '좌(ArrowLeft)' : '우(ArrowRight)';
        let row = scwin.target1.getFocusedRowIndex();
        let col = scwin.target1.getFocusedColumnIndex();
        let editing = scwin.target1.isEditing();
        wf_body_bottom.getObj("scwin").setReturnValue("[방향키 이동] " + dir + " → 이동된 Cell(row=" + row + ", col=" + col + ") 편집모드(isEditing)=" + editing);
    };
    document.addEventListener('keyup', scwin.moveKeyHandler, true);
}
